// schema.gen.ts
//
// GENERATED by scripts/demo-schema.mjs from worker/migrations. Do not edit:
// run `npm run demo-schema` after adding a migration (the deploy and the tests
// check it). Demo mode's store builds its tables from these (demo mode spec §3
// ruling 11) and rebuilds itself when DEMO_SCHEMA_HASH changes.

export const DEMO_SCHEMA: { name: string; sql: string }[] = [
  { name: "0001_init.sql", sql: "-- 0001_init.sql\n--\n-- Plain English: the dashboard's record books. Five tables:\n--   runs      every deploy and destroy ever requested, with timings and result\n--   peers     the clients (phones, laptops) allowed on the tunnel\n--   alerts    things the watchdog noticed while nobody was looking\n--   settings  small key/value overrides changed from the Settings page\n--   cost_days actual daily spend pulled from Azure Cost Management\n\nCREATE TABLE IF NOT EXISTS runs (\n  id                  TEXT PRIMARY KEY,\n  action              TEXT NOT NULL CHECK (action IN ('apply', 'destroy')),\n  status              TEXT NOT NULL,            -- queued | running | success | failure | cancelled\n  requested_at        TEXT NOT NULL,\n  requested_by        TEXT,\n  started_at          TEXT,\n  finished_at         TEXT,\n  github_run_id       INTEGER,\n  github_run_url      TEXT,\n  callback_token_hash TEXT,\n  agent_token_hash    TEXT,\n  payload_json        TEXT,\n  outputs_json        TEXT,\n  public_ip           TEXT,\n  auto_destroy_at     TEXT,\n  reason              TEXT,\n  error               TEXT\n);\n\nCREATE INDEX IF NOT EXISTS runs_requested_at ON runs (requested_at DESC);\n\nCREATE TABLE IF NOT EXISTS peers (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  name        TEXT NOT NULL,\n  public_key  TEXT NOT NULL UNIQUE,\n  ip          TEXT NOT NULL UNIQUE,\n  enabled     INTEGER NOT NULL DEFAULT 1,\n  full_tunnel INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT NOT NULL,\n  note        TEXT\n);\n\nCREATE TABLE IF NOT EXISTS alerts (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  at           TEXT NOT NULL,\n  kind         TEXT NOT NULL,   -- deploy | destroy | failure | drift | cost_guard | idle | unreachable | info\n  message      TEXT NOT NULL,\n  run_id       TEXT,\n  acknowledged INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS alerts_at ON alerts (at DESC);\n\nCREATE TABLE IF NOT EXISTS settings (\n  key   TEXT PRIMARY KEY,\n  value TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS cost_days (\n  day        TEXT PRIMARY KEY,   -- YYYY-MM-DD\n  gbp        REAL NOT NULL,\n  fetched_at TEXT NOT NULL\n);\n" },
  { name: "0002_peer_azure_vnet.sql", sql: "-- 0002_peer_azure_vnet.sql\n--\n-- Plain English: a per-client switch. When on, the client's config also\n-- routes the Azure VNet (10.50.0.0/16) through the tunnel, so the client can\n-- reach workloads that live next to the VM in Azure.\n\nALTER TABLE peers ADD COLUMN azure_vnet INTEGER NOT NULL DEFAULT 0;\n" },
  { name: "0003_run_ssh_password.sql", sql: "-- 0003_run_ssh_password.sql\n--\n-- Plain English: the per-deploy SSH password for azureuser, so the dashboard\n-- can show it in the secret panel. It only works from the SSH allow-list and\n-- dies with the VM.\n\nALTER TABLE runs ADD COLUMN ssh_password TEXT;\n" },
  { name: "0004_peer_tunnel_dns.sql", sql: "-- 0004_peer_tunnel_dns.sql\n--\n-- Plain English: a per-client switch. When on, the client's config points its\n-- DNS at the resolver on the VM loopback (10.13.255.1): ad-blocking and names\n-- like laptop.wg. Full-tunnel clients always use it; for split-tunnel ones it\n-- is a choice, because a client left connected while the VM is destroyed\n-- would have no DNS at all.\n\nALTER TABLE peers ADD COLUMN tunnel_dns INTEGER NOT NULL DEFAULT 0;\n" },
  { name: "0005_profiles_schedules_site.sql", sql: "-- 0005_profiles_schedules_site.sql\n--\n-- Plain English: four additions.\n--   profiles    named deploy presets (\"UK\", \"US exit\"): where and how big\n--   schedules   \"up on these days between these times\", run by the watchman\n--   speedtests  results of the tunnel speed test, Azure <-> home\n--   peers.routes    extra networks reached THROUGH a peer: the home site's LAN\n--   peers.home_lan  whether a client's config sends the home LAN into the tunnel\n\nCREATE TABLE IF NOT EXISTS profiles (\n  id       INTEGER PRIMARY KEY AUTOINCREMENT,\n  name     TEXT NOT NULL UNIQUE,\n  region   TEXT NOT NULL,\n  vm_size  TEXT NOT NULL,\n  sort     INTEGER NOT NULL DEFAULT 0\n);\n\nINSERT INTO profiles (name, region, vm_size, sort) VALUES\n  ('UK', 'uksouth', 'Standard_B1s', 1),\n  ('US exit', 'eastus', 'Standard_B1s', 2),\n  ('EU exit', 'westeurope', 'Standard_B1s', 3);\n\nCREATE TABLE IF NOT EXISTS schedules (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  days        TEXT NOT NULL,              -- ISO weekdays, e.g. \"12345\" = Monday to Friday\n  start_time  TEXT NOT NULL,              -- \"08:00\", Europe/London\n  end_time    TEXT NOT NULL,              -- \"18:00\", later than start_time\n  profile_id  INTEGER,                    -- null = the usual settings\n  enabled     INTEGER NOT NULL DEFAULT 1,\n  created_at  TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS speedtests (\n  id          TEXT PRIMARY KEY,\n  at          TEXT NOT NULL,\n  target_name TEXT,\n  down_mbps   REAL,                       -- Azure -> home\n  up_mbps     REAL,                       -- home -> Azure\n  rtt_ms      REAL,\n  jitter_ms   REAL,\n  error       TEXT\n);\n\nALTER TABLE peers ADD COLUMN routes TEXT NOT NULL DEFAULT '';\nALTER TABLE peers ADD COLUMN home_lan INTEGER NOT NULL DEFAULT 0;\n" },
  { name: "0006_push_subscriptions.sql", sql: "-- 0006_push_subscriptions.sql\n--\n-- Plain English: the phones that turned on alerts in the wg-admin app. Each\n-- row is where that phone's push service accepts messages for it, plus the\n-- two keys its alerts are encrypted to. Deleting a row stops its alerts.\n\nCREATE TABLE IF NOT EXISTS push_subs (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  endpoint    TEXT NOT NULL UNIQUE,\n  p256dh      TEXT NOT NULL,\n  auth        TEXT NOT NULL,\n  label       TEXT,              -- \"Android phone\", from the browser, to tell devices apart\n  created_at  TEXT NOT NULL,\n  last_ok     TEXT,\n  last_error  TEXT\n);\n" },
  { name: "0007_firewall.sql", sql: "-- 0007_firewall.sql\n--\n-- Plain English: the firewall's rule table. Each rule says: traffic from here\n-- to there, of this kind, is allowed or denied. Top to bottom, first match\n-- wins; anything that matches no rule gets the default (deny, unless changed\n-- in Settings). Ends are \"any\", a zone (clients, home, azure, workloads,\n-- internet), one client (by id) or a CIDR.\n--\n-- The starter rules below keep today's behaviour: clients may reach the\n-- internet, Azure, the home LAN and each other; workloads may reach the\n-- internet for updates. Everything else, such as Azure to the home LAN, is\n-- denied until you add a rule for it.\n\nCREATE TABLE IF NOT EXISTS fw_rules (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  position   INTEGER NOT NULL,\n  enabled    INTEGER NOT NULL DEFAULT 1,\n  name       TEXT NOT NULL,\n  src_kind   TEXT NOT NULL CHECK (src_kind IN ('any', 'zone', 'client', 'cidr')),\n  src_value  TEXT NOT NULL DEFAULT '',\n  dst_kind   TEXT NOT NULL CHECK (dst_kind IN ('any', 'zone', 'client', 'cidr')),\n  dst_value  TEXT NOT NULL DEFAULT '',\n  proto      TEXT NOT NULL CHECK (proto IN ('any', 'tcp', 'udp', 'icmp')),\n  ports      TEXT NOT NULL DEFAULT '',\n  action     TEXT NOT NULL CHECK (action IN ('allow', 'deny')),\n  log        INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL\n);\n\nINSERT INTO fw_rules (position, enabled, name, src_kind, src_value, dst_kind, dst_value, proto, ports, action, log, created_at) VALUES\n  (10, 1, 'Clients to the internet (full tunnel)', 'zone', 'clients', 'zone', 'internet', 'any', '', 'allow', 0, '2026-09-24T00:00:00Z'),\n  (20, 1, 'Clients to the Azure VNet', 'zone', 'clients', 'zone', 'azure', 'any', '', 'allow', 0, '2026-09-24T00:00:00Z'),\n  (30, 1, 'Clients to the home LAN', 'zone', 'clients', 'zone', 'home', 'any', '', 'allow', 0, '2026-09-24T00:00:00Z'),\n  (40, 1, 'Clients to each other', 'zone', 'clients', 'zone', 'clients', 'any', '', 'allow', 0, '2026-09-24T00:00:00Z'),\n  (50, 1, 'Workloads to the internet (updates)', 'zone', 'workloads', 'zone', 'internet', 'any', '', 'allow', 0, '2026-09-24T00:00:00Z');\n" },
  { name: "0008_forwards_captures.sql", sql: "-- 0008_forwards_captures.sql\n--\n-- Plain English: two more firewall-appliance features.\n--   fw_forwards  published ports: a public TCP/UDP port on the VM forwarded\n--                to a server behind it (destination NAT), optionally only\n--                from one source network\n--   captures     packet captures taken on the VM, stored in R2 for download\n\nCREATE TABLE IF NOT EXISTS fw_forwards (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  enabled     INTEGER NOT NULL DEFAULT 1,\n  name        TEXT NOT NULL,\n  proto       TEXT NOT NULL CHECK (proto IN ('tcp', 'udp')),\n  public_port INTEGER NOT NULL,\n  target_ip   TEXT NOT NULL,\n  target_port INTEGER NOT NULL,\n  allow_from  TEXT NOT NULL DEFAULT '',\n  created_at  TEXT NOT NULL,\n  UNIQUE (proto, public_port)\n);\n\nCREATE TABLE IF NOT EXISTS captures (\n  id           TEXT PRIMARY KEY,\n  requested_at TEXT NOT NULL,\n  requested_by TEXT,\n  iface        TEXT NOT NULL,\n  filter       TEXT NOT NULL DEFAULT '',\n  seconds      INTEGER NOT NULL,\n  status       TEXT NOT NULL,     -- waiting | running | done | failed\n  bytes        INTEGER,\n  finished_at  TEXT,\n  error        TEXT\n);\n" },
  { name: "0009_audit.sql", sql: "-- 0009_audit.sql\n--\n-- Plain English: the change log. One row each time someone changes the\n-- configuration from the dashboard (a client added, a firewall rule moved, a\n-- setting saved...): when, who, what kind of change, what it was changed on,\n-- and the before and after as JSON. Secrets (keys, passwords, tokens) are\n-- stripped out before a row is written (db.ts audit()). The watchman trims it\n-- to the newest 1000 rows and the last 180 days.\n\nCREATE TABLE IF NOT EXISTS audit (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  at          TEXT NOT NULL,\n  user        TEXT NOT NULL,\n  action      TEXT NOT NULL,     -- e.g. client.add, firewall.rule.move, settings.save\n  target      TEXT NOT NULL DEFAULT '',\n  before_json TEXT,\n  after_json  TEXT\n);\n\nCREATE INDEX IF NOT EXISTS audit_at ON audit (at);\n" },
  { name: "0010_peer_expiry.sql", sql: "-- 0010_peer_expiry.sql\n--\n-- Plain English: two dates on each client.\n--   peers.expires_at         when a guest client stops working (\"1 day\", \"1 week\"...).\n--                            Empty = never. Once it passes, the client is left off\n--                            the VM and the watchman switches it off with a note in\n--                            Activity.\n--   peers.last_handshake_at  the last time the client actually connected, kept\n--                            across tear-downs (the VM's own figure is lost with\n--                            it). Only written when it moves by more than an hour,\n--                            so heartbeats do not rewrite it every 30 seconds.\n--                            Drives the \"no handshake in 30 days\" marker.\n\nALTER TABLE peers ADD COLUMN expires_at TEXT;\nALTER TABLE peers ADD COLUMN last_handshake_at TEXT;\n" },
  { name: "0011_key_rotation.sql", sql: "-- 0011_key_rotation.sql\n--\n-- Plain English: a per-client \"needs new config\" flag for server key\n-- rotation. When the server's public key in wrangler.toml changes, every\n-- client's config still trusts the old key, so each one is flagged. The flag\n-- clears on that client's first handshake with the VM after the change. The\n-- key the dashboard last saw, and when it changed, live in the settings\n-- table (key \"server_key\"), so no table is needed for that.\n\nALTER TABLE peers ADD COLUMN needs_config INTEGER NOT NULL DEFAULT 0;\n" },
  { name: "0012_history.sql", sql: "-- 0012_history.sql\n--\n-- Plain English: the dashboard's own history, like an SNMP poller's\n-- database. Every heartbeat (about every 30 seconds while the VM runs) adds\n-- to a one-minute sample for the VM and one per client. The watchman fills\n-- in the minutes when no heartbeat came, folds samples older than 48 hours\n-- into 5-minute summaries, and deletes anything older than 30 days.\n-- Firewall drops are kept as one row per minute per distinct flow, with a\n-- count. Runs keep their GitHub step list (steps_json).\n--\n-- The tables are WITHOUT ROWID: each row lives in its key index only, so a\n-- write is one row, not two (D1 bills writes per row touched). A client that\n-- is offline, moved no bytes and answered no ping gets no row that minute:\n-- no row means idle and offline.\n\nCREATE TABLE IF NOT EXISTS hist_vm (\n  res          INTEGER NOT NULL,  -- seconds per row: 60 (raw) or 300 (5-minute summary)\n  t            TEXT    NOT NULL,  -- start of the slot, \"YYYY-MM-DDTHH:MM:SSZ\" (UTC)\n  expected     INTEGER NOT NULL,  -- minutes the VM was meant to be up in this slot\n  received     INTEGER NOT NULL,  -- of those, minutes with at least one heartbeat\n  load1        REAL,              -- 1-minute load average\n  rx_rate      REAL,              -- bytes per second into the VM from clients\n  tx_rate      REAL,              -- bytes per second from the VM to clients\n  rx_rate_max  REAL,\n  tx_rate_max  REAL,\n  peers_online INTEGER,\n  dns_up       INTEGER,           -- 1 up, 0 down, NULL not reported\n  PRIMARY KEY (res, t)\n) WITHOUT ROWID;\n\nCREATE TABLE IF NOT EXISTS hist_client (\n  res           INTEGER NOT NULL,\n  t             TEXT    NOT NULL,\n  peer_id       INTEGER NOT NULL,  -- peers.id: stays the same when a client is re-keyed\n  online        INTEGER NOT NULL,  -- 1 if its last handshake was under 3 minutes old\n  handshake_age INTEGER,           -- seconds since its last handshake; NULL = never\n  latency_avg   REAL,              -- ms; NULL = no ping answered\n  latency_max   REAL,\n  rx            INTEGER NOT NULL,  -- bytes the VM received from it in this slot\n  tx            INTEGER NOT NULL,  -- bytes the VM sent to it in this slot\n  PRIMARY KEY (res, t, peer_id)     -- res and time first: the tidy-up reads by time range\n) WITHOUT ROWID;\n\nCREATE TABLE IF NOT EXISTS hist_drops (\n  t      TEXT    NOT NULL,           -- the minute, as above\n  src    TEXT    NOT NULL,\n  dst    TEXT    NOT NULL,\n  proto  TEXT    NOT NULL,\n  dport  INTEGER NOT NULL DEFAULT 0, -- 0 = no port (ICMP and the like)\n  in_if  TEXT    NOT NULL DEFAULT '',\n  out_if TEXT    NOT NULL DEFAULT '',\n  n      INTEGER NOT NULL,           -- drops of this flow in this minute\n  PRIMARY KEY (t, src, dst, proto, dport, in_if, out_if)\n) WITHOUT ROWID;\n\nALTER TABLE runs ADD COLUMN steps_json TEXT;\n" },
  { name: "0013_cost_breakdown.sql", sql: "-- 0013_cost_breakdown.sql\n--\n-- Plain English: Azure's actual cost split by what it was spent on and where.\n-- One row per day, per Azure service name (kept exactly as Azure says it,\n-- for example \"Virtual Machines\" or \"Bandwidth\") and per location (lower\n-- case without spaces, for example \"uksouth\"). The four groups the Cost page\n-- shows (compute, network, disk, other) are worked out when the page is read,\n-- so a change to the grouping needs no migration.\n--\n-- WITHOUT ROWID: each row lives in its key only, so a write is one row.\n-- The key starts with the day, so reading a range and deleting old days both\n-- use it and never read the whole table.\n\nCREATE TABLE IF NOT EXISTS cost_breakdown (\n  day        TEXT NOT NULL,  -- \"YYYY-MM-DD\" (UTC), as in cost_days\n  category   TEXT NOT NULL,  -- Azure's service name, as reported\n  location   TEXT NOT NULL,  -- Azure region id, e.g. \"uksouth\"; \"\" when Azure gave none\n  gbp        REAL NOT NULL,\n  fetched_at TEXT NOT NULL,\n  PRIMARY KEY (day, category, location)\n) WITHOUT ROWID;\n" },
  { name: "0014_fw_history.sql", sql: "-- 0014_fw_history.sql\n--\n-- Plain English: how often each firewall rule matched, over time. Every VM\n-- heartbeat that reports firewall counters adds the increase since the\n-- previous report to a one-minute row per rule that went up (\"r12\" for a\n-- rule, \"default\" for the default action, \"f3\" for a published port).\n-- Same housekeeping as the client history (0012): samples older than 48\n-- hours are folded into 5-minute summaries, and anything older than 30\n-- days is deleted. A rule that did not match in a minute has no row.\n--\n-- WITHOUT ROWID, like the other history tables: a row lives in its key\n-- index only, so a write is one row, and the tidy-up and the reads search\n-- by time without touching a second structure.\n\nCREATE TABLE IF NOT EXISTS hist_fw (\n  res     INTEGER NOT NULL,  -- seconds per row: 60 (raw) or 300 (5-minute summary)\n  t       TEXT    NOT NULL,  -- start of the slot, \"YYYY-MM-DDTHH:MM:SSZ\" (UTC)\n  rule    TEXT    NOT NULL,  -- the counter key: \"r<id>\", \"default\" or \"f<id>\"\n  packets INTEGER NOT NULL,  -- packets that matched in this slot\n  bytes   INTEGER NOT NULL,\n  PRIMARY KEY (res, t, rule)  -- res and time first: the tidy-up reads by time range\n) WITHOUT ROWID;\n" },
  { name: "0015_firewall_draft.sql", sql: "-- 0015_firewall_draft.sql\n--\n-- Plain English: firewall rule edits from the new dashboard go into a draft\n-- first; nothing reaches the VM until Apply. The draft is a full copy of the\n-- rule table (fw_draft_rules), made by the first edit: each copied rule keeps\n-- the live rule's id (live_id says which live rule it edits; null for a rule\n-- added in the draft). fw_policy holds the live rule set's version (bumped by\n-- every apply, restore, default change and old-page edit), the version the\n-- draft began from, the draft's default action, and a one-time token Apply\n-- uses so its whole batch happens only if the version still matched.\n-- The live default action stays in settings (firewall_default).\n\nCREATE TABLE IF NOT EXISTS fw_draft_rules (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  live_id    INTEGER,\n  position   INTEGER NOT NULL,\n  enabled    INTEGER NOT NULL DEFAULT 1,\n  name       TEXT NOT NULL,\n  src_kind   TEXT NOT NULL CHECK (src_kind IN ('any', 'zone', 'client', 'cidr')),\n  src_value  TEXT NOT NULL DEFAULT '',\n  dst_kind   TEXT NOT NULL CHECK (dst_kind IN ('any', 'zone', 'client', 'cidr')),\n  dst_value  TEXT NOT NULL DEFAULT '',\n  proto      TEXT NOT NULL CHECK (proto IN ('any', 'tcp', 'udp', 'icmp')),\n  ports      TEXT NOT NULL DEFAULT '',\n  action     TEXT NOT NULL CHECK (action IN ('allow', 'deny')),\n  log        INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS fw_policy (\n  id            INTEGER PRIMARY KEY CHECK (id = 1),\n  live_version  INTEGER NOT NULL,\n  draft_base    INTEGER,\n  draft_default TEXT CHECK (draft_default IN ('allow', 'deny')),\n  apply_token   TEXT\n);\n\nINSERT OR IGNORE INTO fw_policy (id, live_version) VALUES (1, 1);\n" },
  { name: "0016_run_live_log.sql", sql: "-- 0016_run_live_log.sql\n--\n-- Plain English: a run's live log. GitHub only hands out a job's log once\n-- the job has finished, so while a deploy or tear-down runs, the workflow\n-- posts its own output here a few seconds at a time (infra/ci/live-log.mjs,\n-- POST /api/callback/log). Each piece is one row, numbered by the workflow\n-- (seq), so a piece sent twice after a network blip is stored once. Secrets\n-- are hidden on the runner before sending, and again by the Worker.\n--\n-- Kept small: the newest ~400 KB per run, and the watchman deletes a run's\n-- rows 14 days after it ends. Once a run has finished the dashboard shows\n-- GitHub's full log instead, and falls back to this copy only when GitHub\n-- has none.\n--\n-- WITHOUT ROWID: each row lives in its key index only (one write, not two).\n\nCREATE TABLE IF NOT EXISTS run_live_log (\n  run_id TEXT    NOT NULL,  -- runs.id\n  seq    INTEGER NOT NULL,  -- the workflow's piece number, 1, 2, 3...\n  at     TEXT    NOT NULL,  -- when the Worker received it (ISO, UTC)\n  text   TEXT    NOT NULL,  -- whole lines, each \"<ISO time> <text>\", as GitHub writes its own log\n  PRIMARY KEY (run_id, seq)\n) WITHOUT ROWID;\n" },
  { name: "0017_run_live_log_pruned.sql", sql: "-- 0017_run_live_log_pruned.sql\n--\n-- Plain English: which runs' live logs have had their oldest pieces dropped\n-- to stay under the per-run cap (livelog.ts, db.trimLiveLog), and up to which\n-- piece. The dashboard says \"Earlier lines were dropped\" only for these. A\n-- missing piece 1 is not enough to tell: the Worker turns away a piece that\n-- is too big (413) and the runner skips it, so a log can start at piece 2\n-- with nothing ever dropped.\n--\n-- Deleted with the run's live log by the watchman (db.pruneLiveLogs).\n\nCREATE TABLE IF NOT EXISTS run_live_log_pruned (\n  run_id TEXT    NOT NULL PRIMARY KEY,  -- runs.id\n  upto   INTEGER NOT NULL               -- the highest piece number dropped\n) WITHOUT ROWID;\n" },
  { name: "0018_ui_prefs.sql", sql: "-- 0018_ui_prefs.sql\n--\n-- Plain English: each signed-in person's widget preferences (which widgets\n-- are hidden, their order in a row, and each widget's settings), one row per\n-- person per page. Cosmetic only: never in the backup export, the audit log\n-- or the Activity change log; the dev seeder wipes them.\n--\n-- `version` is the revision a save must name to land (optimistic\n-- concurrency: 1 on the first save, +1 on every save). A reset writes {} and\n-- keeps the row, so the version only ever rises and a stale tab can never\n-- match a recreated row. Spec: docs/superpowers/specs/2026-10-03-widgets-design.md, 6.1.\n\nCREATE TABLE IF NOT EXISTS ui_prefs (\n  user       TEXT    NOT NULL,          -- Access identity email, lower case (c.get(\"user\"))\n  page       TEXT    NOT NULL CHECK (page IN ('overview','clients','firewall','activity','cost')),\n  json       TEXT    NOT NULL,          -- normalised PagePrefs, sparse (only values that differ from defaults), <= 8 KB\n  version    INTEGER NOT NULL,          -- revision for optimistic concurrency: 1 on first save, +1 on every save\n  updated_at TEXT    NOT NULL,          -- ISO, UTC\n  PRIMARY KEY (user, page)\n) WITHOUT ROWID;\n" },
  { name: "0019_azure_insights.sql", sql: "-- 0019_azure_insights.sql\n--\n-- Plain English: what Azure and the VM itself say about the headend, kept\n-- for the new (off-by-default) insight widgets. The collector (a second\n-- cron, worker/src/insights/) asks Azure every few minutes and writes here;\n-- pages only ever read these tables, never Azure. The VM's own vitals arrive\n-- with the heartbeat and add six columns to hist_vm.\n--\n-- Every new table is WITHOUT ROWID, like hist_*: a write is one row (D1\n-- bills writes per row). Times are ISO UTC; history slots use hist_vm's\n-- \"YYYY-MM-DDTHH:MM:SSZ\". Integer binds from the Worker are CAST (D1 binds\n-- every JS number as REAL). None of these tables is in the R2 backup; the\n-- dev seeder wipes them, and only its `insights` story fills them.\n-- Spec: docs/superpowers/specs/2026-10-04-azure-insights-design.md, section 6.\n\n-- The VM's vitals, per heartbeat sample (rolled up like the rest of hist_vm).\nALTER TABLE hist_vm ADD COLUMN mem_used_pct  REAL;  -- (total - available) / total, %\nALTER TABLE hist_vm ADD COLUMN disk_used_pct REAL;  -- of /, %\nALTER TABLE hist_vm ADD COLUMN steal_pct     REAL;  -- CPU steal since the last heartbeat, % (roll-up keeps the max)\nALTER TABLE hist_vm ADD COLUMN conntrack_pct REAL;  -- nf_conntrack count / max, %\nALTER TABLE hist_vm ADD COLUMN net_rtt_ms    REAL;  -- internet check: mean round trip of the targets that answered\nALTER TABLE hist_vm ADD COLUMN net_loss_pct  REAL;  -- internet check: mean loss over the targets, % (roll-up keeps the max)\n\n-- Azure Monitor platform metrics for vm-wg, one wide row per 5-minute slot.\nCREATE TABLE IF NOT EXISTS hist_az_vm (\n  res          INTEGER NOT NULL,  -- seconds per row: 300 only\n  t            TEXT    NOT NULL,  -- start of the slot (UTC)\n  cpu_avg      REAL,              -- Percentage CPU, Average (%)\n  cpu_max      REAL,              -- Percentage CPU, Maximum (%)\n  mem_free_min REAL,              -- Available Memory Bytes, Minimum (bytes)\n  net_in       REAL,              -- Network In Total (bytes per second over the slot)\n  net_out      REAL,              -- Network Out Total (bytes per second over the slot)\n  disk_read    REAL,              -- Disk Read Bytes (bytes per second over the slot)\n  disk_write   REAL,              -- Disk Write Bytes (bytes per second over the slot)\n  disk_rops    REAL,              -- Disk Read Operations/Sec, Average\n  disk_wops    REAL,              -- Disk Write Operations/Sec, Average\n  credits_min  REAL,              -- CPU Credits Remaining, Minimum\n  credits_used REAL,              -- CPU Credits Consumed, Total\n  avail_avg    REAL,              -- VmAvailabilityMetric, Average (0..1)\n  os_iops_max  REAL,              -- OS Disk IOPS Consumed Percentage, Maximum (%)\n  os_bw_max    REAL,              -- OS Disk Bandwidth Consumed Percentage, Maximum (%)\n  PRIMARY KEY (res, t)\n) WITHOUT ROWID;\n\n-- Azure Monitor platform metrics for pip-wg (the IPv4 public IP), one wide row per 5-minute slot.\nCREATE TABLE IF NOT EXISTS hist_az_pip (\n  res             INTEGER NOT NULL,  -- seconds per row: 300 only\n  t               TEXT    NOT NULL,\n  ddos_max        REAL,              -- IfUnderDDoSAttack, Maximum (0 or 1)\n  pkts_in_ddos    REAL,              -- PacketsInDDoS, Maximum (per second)\n  pkts_drop_ddos  REAL,              -- PacketsDroppedDDoS, Maximum (per second)\n  bytes_in_ddos   REAL,              -- BytesInDDoS, Maximum (per second)\n  bytes_drop_ddos REAL,              -- BytesDroppedDDoS, Maximum (per second)\n  packets         REAL,              -- PacketCount, Total (in the slot)\n  bytes           REAL,              -- ByteCount, Total (in the slot)\n  syn             REAL,              -- SynCount, Total (in the slot)\n  vip_avail       REAL,              -- VipAvailability, Average (%)\n  PRIMARY KEY (res, t)\n) WITHOUT ROWID;\n\n-- One row per collector feed: when it last ran, last worked, and is next due.\nCREATE TABLE IF NOT EXISTS az_feed (\n  feed        TEXT PRIMARY KEY,  -- a FeedId (shared/api.ts), or 'housekeeping'\n  last_try_at TEXT,\n  last_ok_at  TEXT,\n  status      TEXT NOT NULL,     -- ok | error | not_configured | skipped | idle\n  error       TEXT,              -- the last error in plain words; never a URL with a signature\n  next_due_at TEXT\n) WITHOUT ROWID;\n\n-- The latest answer of the feeds that keep one document: 'health', 'metricDefs', 'bootlog'.\nCREATE TABLE IF NOT EXISTS az_latest (\n  key        TEXT PRIMARY KEY,\n  json       TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n) WITHOUT ROWID;\n\n-- The Activity Log for the resource group, one row per operation (grouped by correlation id).\nCREATE TABLE IF NOT EXISTS az_activity (\n  id             TEXT PRIMARY KEY,  -- Azure's eventDataId of the row kept\n  at             TEXT NOT NULL,\n  correlation_id TEXT,\n  operation      TEXT NOT NULL,     -- operationName, as Azure gives it\n  status         TEXT NOT NULL,     -- the final status: Succeeded, Failed, or Started/Accepted while still running\n  caller         TEXT,\n  caller_kind    TEXT NOT NULL,     -- wgadmin | person | azure\n  resource_type  TEXT NOT NULL,     -- plain name: Virtual machine, Network security group, ... Other\n  resource_name  TEXT,\n  category       TEXT,              -- Administrative, ResourceHealth, ...\n  level          TEXT\n) WITHOUT ROWID;\nCREATE INDEX IF NOT EXISTS az_activity_at ON az_activity (at);\n\n-- Azure Service Health events that touch VMs or networking.\nCREATE TABLE IF NOT EXISTS az_service_events (\n  tracking_id TEXT PRIMARY KEY,\n  type        TEXT NOT NULL,     -- ServiceIssue | PlannedMaintenance\n  status      TEXT NOT NULL,     -- Active | Resolved\n  level       TEXT,\n  title       TEXT NOT NULL,\n  summary     TEXT,\n  services    TEXT NOT NULL,     -- JSON array of service names\n  regions     TEXT NOT NULL,     -- JSON array of region display names (\"UK South\")\n  starts_at   TEXT,\n  ends_at     TEXT,\n  updated_at  TEXT NOT NULL\n) WITHOUT ROWID;\n\n-- Region capacity and quota, the latest per region (JSON: sizes offered and restricted, vCPU usage).\nCREATE TABLE IF NOT EXISTS az_capacity (\n  region     TEXT PRIMARY KEY,\n  json       TEXT NOT NULL,\n  fetched_at TEXT NOT NULL\n) WITHOUT ROWID;\n\n-- Azure retail list prices in GBP, the latest per region and item.\nCREATE TABLE IF NOT EXISTS az_prices (\n  region     TEXT NOT NULL,\n  item       TEXT NOT NULL,     -- a VM size (Standard_B1s), 'disk:E4', 'disk:S4' or 'ip:v4'\n  gbp        REAL NOT NULL,     -- per unit\n  unit       TEXT NOT NULL,     -- '1 Hour' or '1/Month', as Azure gives it\n  meter      TEXT NOT NULL,     -- Azure's meterName\n  fetched_at TEXT NOT NULL,\n  PRIMARY KEY (region, item)\n) WITHOUT ROWID;\n" },
  { name: "0020_labs.sql", sql: "-- 0020_labs.sql\n--\n-- Plain English: on-demand lab environments (spec\n-- docs/superpowers/specs/2026-10-04-labs-design.md, section 7.1). A lab\n-- session is one deploy of one lab, from Deploy until Azure is clean again;\n-- each workflow run for it (deploy, destroy, peer, unpeer, test) is a\n-- lab_runs row. Nothing is added to runs: its action CHECK allows only apply\n-- and destroy, and SQLite cannot alter a CHECK.\n--\n-- The lab address pool 10.64.0.0/13 is 32 slots of /18 (section 4). A\n-- session holds one slot from deploy until Azure is clean, so two labs never\n-- share addresses. Slot n is 10.64.0.0 + n x 16384: the second octet is\n-- 64 + n / 4 and the third (n % 4) x 64. Reserve with one statement:\n--   UPDATE lab_slots SET session_id = ?1, since = ?2\n--   WHERE slot = (SELECT MIN(slot) FROM lab_slots WHERE session_id IS NULL)\n--     AND session_id IS NULL RETURNING slot, cidr\n--\n-- Times are ISO UTC. Integer binds from the Worker are CAST (D1 binds every\n-- JS number as REAL). The catalogue itself is not here: it is bundled with\n-- the Worker (shared/labs.generated.json). None of these tables is in the R2\n-- backup; the dev seeder wipes them, and only its labs story fills them.\n\nCREATE TABLE IF NOT EXISTS lab_sessions (\n  id               TEXT PRIMARY KEY,     -- \"ls-<stamp>-<rand>\"\n  lab_id           TEXT NOT NULL,\n  lab_version      INTEGER NOT NULL,\n  state            TEXT NOT NULL,        -- deploying | running | failed | tearing_down | ended | ended_dirty\n  test             INTEGER NOT NULL DEFAULT 0,  -- 1 = a release test (section 11.2)\n  region           TEXT NOT NULL,\n  secondary_region TEXT,\n  slot             INTEGER,\n  cidr             TEXT,\n  name_prefix      TEXT NOT NULL,        -- \"l\" + lab number + 5 lowercase characters\n  peering          TEXT NOT NULL,        -- off | waiting | on | disconnected\n  requested_at     TEXT NOT NULL,\n  ready_at         TEXT,\n  ended_at         TEXT,\n  auto_destroy_at  TEXT,                 -- ready_at + hours, never later than max_until\n  max_until        TEXT NOT NULL,        -- requested_at + max_h: nothing moves this\n  warned_at        TEXT,                 -- the 15-minute push went out\n  est_gbp_h        REAL NOT NULL,        -- the estimate per hour at deploy\n  est_gbp          REAL,                 -- the estimate for the whole session, on end\n  end_reason       TEXT,                 -- manual | timer | max | budget | failed | orphan | test\n  outputs_json     TEXT,                 -- { private_ips, connect, users, peer_vnet_id }\n  leftovers_json   TEXT,                 -- what the clean check found (ended_dirty)\n  note             TEXT                  -- the operator's note, at most 2000 characters\n);\nCREATE INDEX IF NOT EXISTS lab_sessions_lab ON lab_sessions (lab_id, requested_at DESC);\nCREATE INDEX IF NOT EXISTS lab_sessions_state ON lab_sessions (state);\n\nCREATE TABLE IF NOT EXISTS lab_runs (\n  id                  TEXT PRIMARY KEY,  -- \"lab-<action>-<stamp>-<rand>\", also the run_live_log key\n  session_id          TEXT NOT NULL,\n  lab_id              TEXT NOT NULL,\n  action              TEXT NOT NULL,     -- deploy | destroy | peer | unpeer | test\n  status              TEXT NOT NULL,     -- queued | running | succeeded | failed | cancelled\n  requested_at        TEXT NOT NULL,\n  requested_by        TEXT,\n  reason              TEXT,\n  started_at          TEXT,\n  finished_at         TEXT,\n  github_run_id       INTEGER,\n  github_run_url      TEXT,\n  callback_token_hash TEXT,\n  admin_password      TEXT,              -- cleared when the session ends, like runs.ssh_password\n  payload_json        TEXT,\n  outputs_json        TEXT,\n  steps_json          TEXT,\n  error               TEXT\n);\nCREATE INDEX IF NOT EXISTS lab_runs_session ON lab_runs (session_id, requested_at DESC);\nCREATE INDEX IF NOT EXISTS lab_runs_requested ON lab_runs (requested_at DESC);\n\nCREATE TABLE IF NOT EXISTS lab_slots (\n  slot       INTEGER PRIMARY KEY,\n  cidr       TEXT NOT NULL,\n  session_id TEXT,                       -- NULL = free\n  since      TEXT\n) WITHOUT ROWID;\n\n-- Azure's daily cost per lab resource group (section 9.4), from one unfiltered\n-- Cost Management query grouped by ResourceGroupName.\nCREATE TABLE IF NOT EXISTS lab_cost_days (\n  day        TEXT NOT NULL,              -- YYYY-MM-DD\n  rg         TEXT NOT NULL,              -- rg-lab-<id> or rg-lab-<id>-<suffix>\n  lab_id     TEXT NOT NULL,\n  gbp        REAL NOT NULL,\n  fetched_at TEXT NOT NULL,\n  PRIMARY KEY (day, rg)\n) WITHOUT ROWID;\n\n-- One row per real-Azure release test (section 11.2). result: pass | fail\n-- (pass needs a clean tear-down, so an empty leftovers list).\nCREATE TABLE IF NOT EXISTS lab_release_tests (\n  lab_id          TEXT NOT NULL,\n  version         INTEGER NOT NULL,\n  at              TEXT NOT NULL,\n  run_id          TEXT NOT NULL,\n  result          TEXT NOT NULL,\n  deploy_seconds  INTEGER,\n  destroy_seconds INTEGER,\n  est_gbp         REAL,\n  leftovers_json  TEXT,\n  PRIMARY KEY (lab_id, version, at)\n) WITHOUT ROWID;\n\n-- The 32 slots, seeded once.\nINSERT OR IGNORE INTO lab_slots (slot, cidr)\nWITH RECURSIVE n(slot) AS (SELECT 0 UNION ALL SELECT slot + 1 FROM n WHERE slot < 31)\nSELECT slot, '10.' || (64 + slot / 4) || '.' || ((slot % 4) * 64) || '.0/18' FROM n;\n\n-- Clients whose \"Azure route\" switch is on now also route the lab pool\n-- (section 7.6), so their config is out of date until they fetch it again.\n-- Only split-tunnel clients: a full-tunnel config already sends everything,\n-- and a site's AllowedIPs are its own routes.\nALTER TABLE peers ADD COLUMN labs_config_due INTEGER NOT NULL DEFAULT 0;\nUPDATE peers SET labs_config_due = 1 WHERE azure_vnet = 1 AND full_tunnel = 0 AND COALESCE(routes, '') = '';\n" },
  { name: "0021_ui_prefs_topology.sql", sql: "-- 0021_ui_prefs_topology.sql\n--\n-- Plain English: lets ui_prefs also hold each person's saved arrangement of a\n-- lab's diagram, one row per person per lab with page 'topology:<lab id>'\n-- (lab topology spec §8.3, ruling 17). SQLite cannot change a CHECK in place,\n-- so the table is rebuilt: a new table with the wider check, every existing\n-- row copied across unchanged (version and updated_at included), the old one\n-- dropped and the new one renamed. Same columns, same key, still WITHOUT\n-- ROWID. The rows stay cosmetic: never in the backup export, the audit log or\n-- the Activity change log; the dev seeder wipes them.\n--\n-- A topology page is 'topology:' and a lab id (az<exam>-<nn>-<slug>), at most\n-- 60 characters in all; anything else is refused, as before.\n\nCREATE TABLE ui_prefs_new (\n  user       TEXT    NOT NULL,          -- Access identity email, lower case (c.get(\"user\"))\n  page       TEXT    NOT NULL CHECK (\n               page IN ('overview','clients','firewall','activity','cost')\n               OR (page GLOB 'topology:az[0-9][0-9][0-9]-[0-9][0-9]-*' AND length(page) <= 60)\n             ),\n  json       TEXT    NOT NULL,          -- widgets: normalised PagePrefs <= 8 KB; topology: TopologyLayout <= 16 KB\n  version    INTEGER NOT NULL,          -- revision for optimistic concurrency: 1 on first save, +1 on every save\n  updated_at TEXT    NOT NULL,          -- ISO, UTC\n  PRIMARY KEY (user, page)\n) WITHOUT ROWID;\n\nINSERT INTO ui_prefs_new (user, page, json, version, updated_at)\n  SELECT user, page, json, version, updated_at FROM ui_prefs;\n\nDROP TABLE ui_prefs;\n\nALTER TABLE ui_prefs_new RENAME TO ui_prefs;\n" },
  { name: "0022_demo_mode.sql", sql: "-- 0022_demo_mode.sql\n--\n-- Plain English: who is looking at demo data (demo mode spec §3 ruling 5).\n-- One row per person who switched demo mode on; no row means real data. The\n-- Worker reads it on every request, so the switch takes effect at once\n-- everywhere (D1, not KV, which can serve a stale copy for a minute). It is\n-- the only real-store write demo mode makes. Cosmetic like ui_prefs: never in\n-- the backup export, restore, audit log or Activity, and the dev seeder never\n-- wipes it.\n\nCREATE TABLE IF NOT EXISTS demo_mode (\n  user  TEXT PRIMARY KEY,        -- Access identity email, lower case (c.get(\"user\"))\n  since TEXT NOT NULL            -- ISO, UTC: when this person switched it on\n) WITHOUT ROWID;\n" },
];

export const DEMO_SCHEMA_HASH = "1d20b2b3985df738dd2377b68e7d7a88ca79ff3daf2378868a0847978268816f";
